template.yaml:
concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

concurrency:
  group: ${{ github.workflow }}-${{ github.event.pull_request.head.sha || github.sha }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' }}

template.workflow:
# Adds the `review:breaking` label to any dependabot PR whose title matches a
# major-version bump. Pairs with the grouping config in `.github/dependabot.yml`
#: groups handle patch/minor churn in one PR; majors arrive individually
# and this workflow flags them for conscious review.

name: Label Major Dependabot PRs

on:
  pull_request_target:
    types: [opened, reopened, edited, synchronize]

permissions:
  pull-requests: write
  issues: write

jobs:
  label:
    if: github.actor == 'dependabot[bot]'
    runs-on: ubuntu-latest
    steps:
      - name: Detect major-version bump and label
        uses: actions/github-script@v9
        with:
          script: |
            const pr = context.payload.pull_request;
            const title = pr.title || '';
            // Dependabot major-bump titles look like:
            //   "deps: bump ajv from 7.x.x to 8.x.x"
            //   "deps: bump @scope/pkg from 1.2.3 to 2.0.0"
            // Extract the two version triplets and compare majors.
            const re = /from\s+v?(\d+)\.\d+\.\d+(?:\S*)?\s+to\s+v?(\d+)\.\d+\.\d+/i;
            const match = title.match(re);
            if (!match) {
              core.info(`PR title "${title}" did not match version-bump pattern; skipping.`);
              return;
            }
            const [fromMajor, toMajor] = [Number(match[1]), Number(match[2])];
            if (toMajor <= fromMajor) {
              core.info(`PR title "${title}" is not a major bump (${fromMajor} -> ${toMajor}); skipping.`);
              return;
            }
            core.info(`Major bump detected: ${fromMajor} -> ${toMajor}. Applying review:breaking label.`);
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              labels: ['review:breaking'],
            });

template.yaml:
- name: Deploy to Vercel
  uses: amondnet/vercel-action@v25
  with:
    vercel-token: ${{ secrets.VERCEL_TOKEN }}
    vercel-org-id: ${{ secrets.VERCEL_ORG_ID }}
    vercel-project-id: ${{ secrets.VERCEL_PROJECT_ID }}

- name: Deploy to Railway
  run: railway up --service ${{ vars.RAILWAY_SERVICE }}
  env:
    RAILWAY_TOKEN: ${{ secrets.RAILWAY_TOKEN }}
